"use client";

import { loadFont } from "@remotion/google-fonts/Lexend";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_FIELDS,
  DEFAULT_HEADLINE,
  DEFAULT_RSVP,
  DEFAULT_RSVP_LABEL,
  type InviteField,
  type RsvpElementId,
  rowsOf,
  rsvpTimeline,
  splitWords,
} from "./timeline";

const lexend = loadFont("normal", {
  weights: ["300", "400", "500"],
  subsets: ["latin"],
});

export type RsvpField = InviteField;

export interface RsvpProps {
  headline?: string;
  fields?: RsvpField[];
  rsvpLabel?: string;
  rsvp?: string;
  accent?: string;
  /** Text color of the headline and values; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the copy. Load it yourself; Lexend by default. */
  fontFamily?: string;
  /** Weight of the headline. */
  fontWeight?: number;
  /** Frames between headline words as they rise in. */
  stagger?: number;
  /** Size of the invite, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches single headline words, rows and the focus on
   * the RSVP, by the ids in `./timeline`. Frames on the scene timeline,
   * after `delay` and `speed`.
   */
  timing?: Timing<RsvpElementId>;
}

const THEMES = {
  dark: { bg: "#E8392B", ink: "#FFFFFF", accent: "#0A0A0A" },
  light: { bg: "#FFFFFF", ink: "#0A0A0A", accent: "#E8392B" },
} as const;

const TRACK = -0.035;
const ROW_TRACK = -0.012;
const LH = 1.04;
const ROW_LH = 1.2;
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Spec {
  text: string;
  weight: number;
}

function useWidths(specs: Spec[], fontFamily: string) {
  const key = specs.map((s) => `${s.weight}|${s.text}`).join("\u0001");
  const [state, setState] = useState<{
    key: string;
    w: Record<string, number>;
  } | null>(null);
  const [handle] = useState(() => delayRender("rsvp: measuring"));
  const released = useRef(false);
  const ref = useRef(specs);
  ref.current = specs;
  useEffect(() => {
    let live = true;
    const weights = Array.from(new Set(ref.current.map((s) => s.weight)));
    Promise.all([
      lexend.waitUntilDone(),
      ...weights.map((wt) =>
        document.fonts.load(`${wt} 100px "${fontFamily}"`),
      ),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const ctx = document.createElement("canvas").getContext("2d");
        const w: Record<string, number> = {};
        for (const s of ref.current) {
          const k = `${s.weight}|${s.text}`;
          if (ctx) {
            ctx.font = `${s.weight} 100px "${fontFamily}"`;
            w[k] = ctx.measureText(s.text).width / 100;
          } else {
            w[k] = s.text.length * 0.56;
          }
        }
        setState({ key, w });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle, fontFamily]);
  return state && state.key === key ? state.w : null;
}

function greedy(
  words: string[],
  adv: (s: string) => number,
  space: number,
  maxEm: number,
) {
  const lines: string[][] = [];
  let line: string[] = [];
  let x = 0;
  for (const word of words) {
    const w = adv(word);
    if (line.length > 0 && x + space + w > maxEm) {
      lines.push(line);
      line = [word];
      x = w;
    } else {
      x += (line.length > 0 ? space : 0) + w;
      line.push(word);
    }
  }
  if (line.length > 0) lines.push(line);
  return lines;
}

function balanced(
  words: string[],
  adv: (s: string) => number,
  space: number,
  maxEm: number,
) {
  const base = greedy(words, adv, space, maxEm);
  if (base.length <= 1) return base;
  let lo = 0;
  let hi = maxEm;
  for (let k = 0; k < 24; k++) {
    const mid = (lo + hi) / 2;
    if (greedy(words, adv, space, mid).length <= base.length) hi = mid;
    else lo = mid;
  }
  return greedy(words, adv, space, hi);
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function Rsvp(props: RsvpProps) {
  const {
    headline = DEFAULT_HEADLINE,
    fields = DEFAULT_FIELDS,
    rsvpLabel = DEFAULT_RSVP_LABEL,
    rsvp = DEFAULT_RSVP,
    accent,
    ink,
    background,
    fontFamily = lexend.fontFamily,
    fontWeight = 500,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(rsvpTimeline, props, durationInFrames * speed, timing);
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const fg = ink ?? c.ink;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const rows = rowsOf(fields, rsvpLabel, rsvp);
  const headWords = splitWords(headline);
  const rowWords = rows.map((r) => splitWords(r.value));
  const w = useWidths(
    [
      { text: " ", weight: fontWeight },
      { text: " ", weight: 400 },
      ...headWords.map((text) => ({ text, weight: fontWeight })),
      ...rows.map((r) => ({ text: r.label, weight: 400 })),
      ...rowWords.flat().map((text) => ({ text, weight: 400 })),
    ],
    fontFamily,
  );

  if (!w) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const headAdv = (s: string) =>
    (w[`${fontWeight}|${s}`] ?? s.length * 0.56) + TRACK * Array.from(s).length;
  const rowAdv = (s: string) =>
    (w[`400|${s}`] ?? s.length * 0.56) + ROW_TRACK * Array.from(s).length;
  const headSpace = w[`${fontWeight}| `] ?? 0.25;
  const rowSpace = w["400| "] ?? 0.25;

  const portrait = H > W * 1.1;
  const mx = W * (portrait ? 0.08 : 0.07);
  const availW = W - mx * 2;
  const labelEm = Math.max(0, ...rows.map((r) => rowAdv(r.label)));

  let fH = portrait ? W * 0.2 : H * 0.2;
  let fR = portrait ? W * 0.064 : H * 0.054;
  const labelH = portrait ? ROW_LH * 0.72 : 0;
  const build = () => {
    const headLines = balanced(headWords, headAdv, headSpace, availW / fH);
    const labelCol = portrait
      ? 0
      : Math.max(labelEm * fR + fR * 1.4, availW * 0.2);
    const valueW = availW - labelCol;
    const valueLines = rowWords.map((ws) =>
      balanced(ws, rowAdv, rowSpace, valueW / fR),
    );
    const headH = headLines.length * LH * fH;
    const gapHR = fH * (portrait ? 0.5 : 0.36);
    const rowGap = fR * (portrait ? 0.9 : 0.62);
    const rowHs = valueLines.map(
      (ls) => (labelH + Math.max(1, ls.length) * ROW_LH) * fR,
    );
    const rowsH =
      rowHs.reduce((a, b) => a + b, 0) + rowGap * Math.max(0, rowHs.length - 1);
    return {
      headLines,
      labelCol,
      valueLines,
      headH,
      gapHR,
      rowGap,
      rowHs,
      rowsH,
      total: headH + gapHR + rowsH,
    };
  };
  let B = build();
  const maxH = H * (portrait ? 0.76 : 0.82);
  for (let k = 0; k < 80; k++) {
    if (B.total <= maxH && B.headLines.length <= (portrait ? 3 : 2)) break;
    fH *= 0.96;
    fR *= 0.97;
    B = build();
  }

  const top = portrait
    ? (H - B.total) / 2 - H * 0.02
    : Math.max(H * 0.09, (H - B.total) / 2 - H * 0.04);
  const rowsTop = top + B.headH + B.gapHR;

  const n = rows.length;
  const focusEl = rsvp && n > 0 ? tl.get("focus") : null;
  const focus = focusEl
    ? interpolate(t, [focusEl.start, focusEl.end], [0, 1], {
        ...CLAMP,
        easing: EASE_IO,
      })
    : 0;

  let wordIndex = 0;
  const headNodes = B.headLines.map((line, li) => (
    <div
      key={`h${li}`}
      style={{
        position: "absolute",
        left: mx,
        top: top + li * LH * fH,
        height: LH * fH,
        lineHeight: `${LH * fH}px`,
        fontSize: fH,
        fontWeight,
        whiteSpace: "pre",
        letterSpacing: `${TRACK}em`,
        color: fg,
      }}
    >
      {line.map((word, wi) => {
        const hw = tl.get(`word:${wordIndex}`);
        wordIndex++;
        const e = interpolate(t, [hw.start, hw.end], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        return (
          <span key={`hw${wi}`}>
            {wi > 0 ? " " : ""}
            <span
              style={{
                display: "inline-block",
                opacity: e,
                transform: `translateY(${((1 - e) * fH * 0.3).toFixed(2)}px)${glide(midway(e))}`,
              }}
            >
              {word}
            </span>
          </span>
        );
      })}
    </div>
  ));

  let y = rowsTop;
  const rowNodes = rows.map((row, k) => {
    const rowTop = y;
    y += B.rowHs[k] + B.rowGap;
    const re = tl.get(`row:${k}`);
    const at = re.start;
    const le = interpolate(t, [at, at + re.beat("label")], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const isRsvp = Boolean(rsvp) && k === n - 1;
    const dim = isRsvp ? 1 : 1 - 0.45 * focus;
    return (
      <div
        key={`r${k}`}
        style={{
          position: "absolute",
          left: mx,
          top: rowTop,
          width: availW,
          height: B.rowHs[k],
          fontSize: fR,
          lineHeight: `${ROW_LH * fR}px`,
          letterSpacing: `${ROW_TRACK}em`,
          whiteSpace: "pre",
          opacity: dim,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            fontSize: portrait ? fR * 0.62 : fR,
            lineHeight: `${(portrait ? labelH : ROW_LH) * fR}px`,
            fontWeight: 400,
            color: hi,
            opacity: le,
            transform: `translateY(${((1 - le) * fR * 0.5).toFixed(2)}px)${glide(midway(le))}`,
          }}
        >
          {row.label}
        </div>
        <div
          style={{
            position: "absolute",
            left: B.labelCol,
            top: labelH * fR,
            fontWeight: 400,
            color: isRsvp ? hi : fg,
          }}
        >
          {B.valueLines[k].map((line, li) => {
            const before = B.valueLines[k]
              .slice(0, li)
              .reduce((a, l) => a + l.length, 0);
            return (
              <div key={`v${li}`}>
                {line.map((word, wi) => {
                  const s =
                    at + re.beat("words") + (before + wi) * re.beat("wordStep");
                  const e = interpolate(t, [s, s + re.beat("word")], [0, 1], {
                    ...CLAMP,
                    easing: EASE_OUT,
                  });
                  return (
                    <span key={`vw${wi}`}>
                      {wi > 0 ? " " : ""}
                      <span
                        style={{
                          display: "inline-block",
                          opacity: e,
                          transform: `translateY(${((1 - e) * fR * 0.55).toFixed(2)}px)${glide(midway(e))}`,
                        }}
                      >
                        {word}
                      </span>
                    </span>
                  );
                })}
              </div>
            );
          })}
        </div>
      </div>
    );
  });

  return (
    <AbsoluteFill
      style={{
        background: stage,
        overflow: "hidden",
        fontFamily,
      }}
    >
      <ScaleLayer scale={scale}>
        {headNodes}
        {rowNodes}
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// Each headline word rising in, each row of the invite (its label, then its
// words), and the focus that dims the other rows onto the RSVP. Frames on the
// 30 fps scene timeline, after `delay` and `speed`. The rows spread over the
// first half of the clip, so their pace follows the clip length. The ids are
// public: a saved `timing` prop refers to them.

export type RsvpElementId = `word:${number}` | `row:${number}` | "focus";

/** One row of the invite (`RsvpField`). */
export interface InviteField {
  label: string;
  value: string;
}

export interface RsvpTimingProps {
  headline?: string;
  fields?: InviteField[];
  rsvpLabel?: string;
  rsvp?: string;
  stagger?: number;
}

export const DEFAULT_HEADLINE = "You’re invited.";
export const DEFAULT_RSVP_LABEL = "RSVP";
export const DEFAULT_RSVP = "npx shadcn add @remocn/whip-pan";

export const DEFAULT_FIELDS: InviteField[] = [
  { label: "What", value: "Your launch film" },
  { label: "When", value: "Whenever you’re ready" },
  { label: "Where", value: "Your own repo" },
  { label: "Bring", value: "The story. We brought the parts." },
];

export const splitWords = (s: string) => s.split(/\s+/).filter(Boolean);

/** The rows shown: the filled fields, then the RSVP row when there is one. */
export function rowsOf(fields: InviteField[], rsvpLabel: string, rsvp: string) {
  return [
    ...fields.filter((f) => f.label || f.value),
    ...(rsvp ? [{ label: rsvpLabel, value: rsvp }] : []),
  ];
}

const WORD_AT = 3;
const WORD_LEN = 20;
const ROW_START = 26;
const LABEL = 14;
const ROW_WORDS = 5;
const ROW_WORD_STEP = 2;
const ROW_WORD = 16;

// `word:<i>` is headline word `i`; they form a chain. `row:<k>` is row `k`:
// its label rises over `label`, its words from `words` on, one every
// `wordStep`, each over `word`. The rows form a chain; the RSVP row comes 10
// frames late. `focus` dims the other rows and follows the RSVP row.
export const rsvpTimeline = defineTimeline<RsvpElementId, RsvpTimingProps>(
  (
    {
      headline = DEFAULT_HEADLINE,
      fields = DEFAULT_FIELDS,
      rsvpLabel = DEFAULT_RSVP_LABEL,
      rsvp = DEFAULT_RSVP,
      stagger = 4,
    },
    { length },
  ) => {
    const headWords = splitWords(headline);
    const rows = rowsOf(fields, rsvpLabel, rsvp);
    const n = rows.length;
    const span = Math.max(
      n * 10,
      Math.min(length * 0.5, length - 70) - ROW_START,
    );
    const rowStep = Math.min(16, span / Math.max(1, n));
    const rowAt = (k: number) =>
      ROW_START + k * rowStep + (rsvp && k === n - 1 ? 10 : 0);
    const lastAt = rowAt(n - 1);
    const elements: TimelineElement<RsvpElementId>[] = [
      ...headWords.map(
        (word, i): TimelineElement<RsvpElementId> => ({
          id: `word:${i}`,
          lane: "Headline",
          label: word,
          start: WORD_AT + i * stagger,
          length: WORD_LEN,
          follows: i > 0 ? `word:${i - 1}` : undefined,
        }),
      ),
      ...rows.map((row, k): TimelineElement<RsvpElementId> => {
        const m = splitWords(row.value).length;
        return {
          id: `row:${k}`,
          lane: "Rows",
          label: row.label || row.value,
          start: rowAt(k),
          length: Math.max(
            LABEL,
            m > 0 ? ROW_WORDS + (m - 1) * ROW_WORD_STEP + ROW_WORD : 0,
          ),
          follows: k > 0 ? `row:${k - 1}` : undefined,
          beats: {
            label: LABEL,
            words: ROW_WORDS,
            wordStep: ROW_WORD_STEP,
            word: ROW_WORD,
          },
        };
      }),
    ];
    if (rsvp && n > 0) {
      elements.push({
        id: "focus",
        lane: "Focus",
        label: "Focus on RSVP",
        start: lastAt + 12,
        length: 18,
        follows: `row:${n - 1}`,
      });
    }
    return elements.sort((a, b) => a.start - b.start);
  },
);
